# update_account_drawer_ui_v3.ps1
# Replaces the emoji rocket with a stylized gradient rocket icon
# (dark rounded box + small stars + tilted gradient rocket) to more
# closely match the reference art. No new dependencies/assets needed.
#
# Run from the stockpro-frontend repo root (the folder that contains 'lib').
# Usage:  powershell -ExecutionPolicy Bypass -File update_account_drawer_ui_v3.ps1

$ErrorActionPreference = "Stop"

$targetRelPath = "lib\shared\widgets\account_drawer.dart"
$targetPath = Join-Path (Get-Location) $targetRelPath

if (-not (Test-Path (Split-Path $targetPath -Parent))) {
    Write-Host "ERROR: Can't find $targetRelPath from here." -ForegroundColor Red
    Write-Host "Run this script from the stockpro-frontend repo root (the folder that contains 'lib')." -ForegroundColor Yellow
    exit 1
}

$base64Content = ""

$bytes = [Convert]::FromBase64String($base64Content)
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($targetPath, $utf8NoBom.GetString($bytes), $utf8NoBom)

Write-Host "Updated: $targetRelPath" -ForegroundColor Green
Write-Host "Rocket icon replaced with a gradient-styled rocket + stars in a dark rounded box." -ForegroundColor Cyan
Write-Host "Next: flutter run" -ForegroundColor Cyan
